77	
78	interface SearchResult {
79	  name: string;
80	  description: string;
81	  weeklyDownloads: number;
82	}
83	
84	interface NpmSearchResponse {
85	  objects: {
86	    package: { name: string; description?: string; date?: string };
87	    downloads?: { weekly: number };
88	  }[];
89	}
90	
91	interface NpmLatestManifest {
92	  version: string;
93	  description?: string;
94	  license?: string;
95	  deprecated?: string;
96	  repository?: string | { url?: string };
97	}
98	
99	type PackageInfo =
100	  | { found: false; name: string }
101	  | {
102	      found: true;
103	      name: string;
104	      description: string;
105	      latestVersion: string;
106	      lastPublished: string | null;
107	      monthsSinceLastPublish: number | null;
108	      license: string | null;
109	      repository: string | null;
110	      weeklyDownloads: number | null;
111	      deprecated: string | null;
112	    };
113	
114	const searchPackages = span(
115	  { kind: "TOOL", toolName: "search_packages" },
116	  async (query: string): Promise<SearchResult[]> => {
117	    const url = `https://registry.npmjs.org/-/v1/search?text=${encodeURIComponent(query)}&size=25`;
118	
119	    const res = await fetch(url);
120	    if (!res.ok) throw new Error(`npm search failed with status ${res.status}`);
121	
122	    const data = (await res.json()) as NpmSearchResponse;
123	
124	    return data.objects
125	      .map((o) => ({
126	        name: o.package.name,
127	        description: o.package.description ?? "",
128	        weeklyDownloads: o.downloads?.weekly ?? 0,
129	      }))
130	      .sort((a, b) => b.weeklyDownloads - a.weeklyDownloads)
131	      .slice(0, 8);
132	  },
133	);
134	
135	const getPackageInfo = span(
136	  { kind: "TOOL", toolName: "get_package_info" },
137	  async (name: string): Promise<PackageInfo> => {
138	    const encoded = encodeURIComponent(name).replace("%40", "@");
139	    const [latestRes, searchRes] = await Promise.all([
140	      fetch(`https://registry.npmjs.org/${encoded}/latest`),
141	      fetch(
142	        `https://registry.npmjs.org/-/v1/search?text=${encodeURIComponent(name)}&size=5`,
143	      ),
144	    ]);
145	
146	    if (latestRes.status === 404) return { found: false, name };
147	    if (!latestRes.ok)
148	      throw new Error(
149	        `npm lookup for ${name} failed with status ${latestRes.status}`,
150	      );
151	
152	    const latest = (await latestRes.json()) as NpmLatestManifest;
153	
154	    const search = searchRes.ok
155	      ? ((await searchRes.json()) as NpmSearchResponse)
156	      : { objects: [] };
157	
158	    const match = search.objects.find((o) => o.package.name === name);
159	
160	    return {
161	      found: true,
162	      name,
163	      description: latest.description ?? "",
164	      latestVersion: latest.version,
165	      lastPublished: match?.package.date ?? null,
166	      monthsSinceLastPublish: monthsSince(match?.package.date),
167	      license: latest.license ?? null,
168	      repository: normalizeRepository(latest.repository),
169	      weeklyDownloads: match?.downloads?.weekly ?? null,
170	      deprecated: latest.deprecated ?? null,
171	    };
172	  },
173	);
174	
175	const MS_PER_MONTH = 1000 * 60 * 60 * 24 * 30.44;
176	
177	function monthsSince(isoDate: string | undefined): number | null {
178	  if (!isoDate) return null;
179	  const then = Date.parse(isoDate);
180	  if (Number.isNaN(then)) return null;
181	  return Math.floor((Date.now() - then) / MS_PER_MONTH);
182	}
183	
184	function normalizeRepository(
185	  repo: NpmLatestManifest["repository"],
186	): string | null {
187	  const raw = typeof repo === "string" ? repo : repo?.url;
188	  if (!raw) return null;
189	  return raw
190	    .replace(/^git\+/, "")
191	    .replace(/^github:/, "https://github.com/")
192	    .replace(/^git:\/\//, "https://")
193	    .replace(/\.git$/, "")
194	    .toLowerCase();
195	}
196	
197	async function runTool(name: string, rawArgs: string): Promise<string> {
198	  const args: unknown = JSON.parse(rawArgs);
199	
200	  if (name === "search_packages" && isQueryArgs(args)) {
201	    return JSON.stringify(await searchPackages(args.query));
202	  }
203	
204	  if (name === "get_package_info" && isNameArgs(args)) {
205	    return JSON.stringify(await getPackageInfo(args.name));
206	  }
207	
208	  return JSON.stringify({ error: `Unknown tool or bad args: ${name}` });
209	}
210	
211	function isQueryArgs(value: unknown): value is { query: string } {
212	  return (
213	    typeof value === "object" &&
214	    value !== null &&
215	    "query" in value &&
216	    typeof value.query === "string"
217	  );
218	}
219	
220	function isNameArgs(value: unknown): value is { name: string } {
221	  return (
222	    typeof value === "object" &&
223	    value !== null &&
224	    "name" in value &&
225	    typeof value.name === "string"
226	  );
227	}
