229	const runAgent = span(
230	  { kind: "AGENT", name: "npm_advisor" },
231	  async (question: string): Promise<string> => {
232	    const messages: ChatCompletionMessageParam[] = [
233	      {
234	        role: "system",
235	        content: [
236	          "You help developers pick npm packages. Follow these steps in order.",
237	          "1. From your own knowledge, name the 3 to 5 packages developers most often choose for this job.",
238	          "2. In your first turn, call get_package_info on each of them and call search_packages to find anything you missed.",
239	          "3. If search shows a strong candidate you have not checked, call get_package_info on it.",
240	          "4. Recommend one package and at most two alternatives. Each must be a library developers install directly for this job.",
241	          "   Skip packages that extend, wrap or ship inside another library. Packages with the same repository are one project: list it once.",
242	          "monthsSinceLastPublish is how long ago the last release was. At 12 or more, the package may be unmaintained:",
243	          "   never make it the main pick, and if you list it as an alternative, say how many months it has been.",
244	          "   High downloads do not mean a package is maintained. Never call a package actively maintained at 12 or more.",
245	          "Give downloads and last publish date for each pick.",
246	        ].join("\n"),
247	      },
248	      { role: "user", content: question },
249	    ];
250	
251	    for (let step = 1; step <= MAX_STEPS; step++) {
252	      const res = await client.chat.completions.create({
253	        model,
254	        messages,
255	        tools,
256	      });
257	
258	      const msg = res.choices[0]?.message;
259	      if (!msg) throw new Error("Model returned no message");
260	      messages.push(msg);
261	
262	      if (!msg.tool_calls?.length) return msg.content ?? "";
263	
264	      const calls = msg.tool_calls.filter((call) => call.type === "function");
265	      const results = await Promise.all(
266	        calls.map(async (call) => {
267	          console.log(
268	            `[step ${step}] ${call.function.name}(${call.function.arguments})`,
269	          );
270	          return {
271	            id: call.id,
272	            content: await runTool(call.function.name, call.function.arguments),
273	          };
274	        }),
275	      );
276	      for (const { id, content } of results) {
277	        messages.push({ role: "tool", tool_call_id: id, content });
278	      }
279	    }
280	    return `Stopped after ${MAX_STEPS} steps without a final answer.`;
281	  },
282	);
