// Pure text helpers shared by the agent and the eval runner. No I/O here, so
// tests can import this file without API keys or a neatlogs connection.

function escapeRegExp(text: string): string {
  return text.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

/**
 * Package names from `names` that appear in `text` as whole names.
 * "moment" matches "**moment**" and "Moment.js", but not "moment-timezone"
 * or the "/moment" inside a GitHub URL.
 */
export function mentionedPackages(text: string, names: string[]): string[] {
  return names.filter((name) =>
    new RegExp(
      `(?<![\\w@/.-])${escapeRegExp(name)}(?![\\w@/-]|\\.(?!js\\b)\\w)`,
      "i",
    ).test(text),
  );
}

export interface EvalRow {
  caseId: string;
  run: number;
  traceId: string;
  trapsMentioned: string[];
}

/** The results table from evals.md, with Main, Alts and Trap left for a human to score. */
export function resultsTable(rows: EvalRow[]): string {
  const lines = [
    "| Question | Run | Main | Alts | Trap | Trace | Notes |",
    "| -------- | --- | ---- | ---- | ---- | ----- | ----- |",
    ...rows.map((r) => {
      const notes = r.trapsMentioned.length
        ? `Mentions trap: ${r.trapsMentioned.map((t) => `\`${t}\``).join(", ")}`
        : "";
      return `| ${r.caseId} | ${r.run} | | | | \`${r.traceId}\` | ${notes} |`;
    }),
  ];
  return lines.join("\n");
}

import { describe, expect, it } from "vitest";
import { mentionedPackages, resultsTable } from "./report.ts";

describe("mentionedPackages", () => {
  it("finds names in markdown formatting and in any case", () => {
    const text = "Main pick: **date-fns**. Also `Luxon` and Moment.js.";
    expect(mentionedPackages(text, ["date-fns", "luxon", "moment"])).toEqual([
      "date-fns",
      "luxon",
      "moment",
    ]);
  });

  it("matches a name at the end of a sentence", () => {
    expect(mentionedPackages("Avoid recoil.", ["recoil"])).toEqual(["recoil"]);
  });

  it("ignores longer names that contain the name", () => {
    const text = "Use moment-timezone with @tanstack/react-form-devtools.";
    expect(
      mentionedPackages(text, ["moment", "@tanstack/react-form", "react-form"]),
    ).toEqual([]);
  });

  it("ignores the name inside a repository URL", () => {
    const text = "[Repository](https://github.com/moment/moment)";
    expect(mentionedPackages(text, ["moment"])).toEqual([]);
  });

  it("does not count redux inside @reduxjs/toolkit or react-redux", () => {
